CREATE DATABASE IF NOT EXISTS day9_telecom; USE day9_telecom;
CREATE TABLE subscribers(subscriber_id INT PRIMARY KEY AUTO_INCREMENT,subscriber_name VARCHAR(120) NOT NULL,phone_number VARCHAR(20) NOT NULL,subscriber_type VARCHAR(20) NOT NULL,balance DECIMAL(10,2) NOT NULL DEFAULT 0,plan_name VARCHAR(50) NOT NULL,validity_end DATE NOT NULL) ENGINE=InnoDB;
CREATE TABLE recharge_history(recharge_id BIGINT PRIMARY KEY AUTO_INCREMENT,subscriber_id INT NOT NULL,amount DECIMAL(10,2) NOT NULL,plan_name VARCHAR(50) NOT NULL,recharged_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,balance_after DECIMAL(10,2) NOT NULL,FOREIGN KEY(subscriber_id) REFERENCES subscribers(subscriber_id)) ENGINE=InnoDB;
CREATE TABLE subscriber_notifications(notification_id BIGINT PRIMARY KEY AUTO_INCREMENT,subscriber_id INT NOT NULL,message VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(subscriber_id) REFERENCES subscribers(subscriber_id)) ENGINE=InnoDB;
